mapper.select:
SELECT FROM support_inquiries si JOIN users u ON u.user_id = si.user_id
WHERE si.status = #{status}
ORDER BY CASE si.status WHEN 'OPEN' THEN 0 WHEN 'IN_PROGRESS' THEN 1 WHEN 'ANSWERED' THEN 2 ELSE 3 END, si.updated_at DESC, si.support_inquiry_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE support_inquiries
SET status = #{status}
WHERE support_inquiry_id = #{inquiryId}
